<?php
namespace App\Services;
use DomainException;
final class SalesSettingsService {
 public function __construct(private int $shop){}
 public static function states():array {return ['01'=>'Jammu and Kashmir','02'=>'Himachal Pradesh','03'=>'Punjab','04'=>'Chandigarh','05'=>'Uttarakhand','06'=>'Haryana','07'=>'Delhi','08'=>'Rajasthan','09'=>'Uttar Pradesh','10'=>'Bihar','11'=>'Sikkim','12'=>'Arunachal Pradesh','13'=>'Nagaland','14'=>'Manipur','15'=>'Mizoram','16'=>'Tripura','17'=>'Meghalaya','18'=>'Assam','19'=>'West Bengal','20'=>'Jharkhand','21'=>'Odisha','22'=>'Chhattisgarh','23'=>'Madhya Pradesh','24'=>'Gujarat','26'=>'Dadra and Nagar Haveli and Daman and Diu','27'=>'Maharashtra','29'=>'Karnataka','30'=>'Goa','31'=>'Lakshadweep','32'=>'Kerala','33'=>'Tamil Nadu','34'=>'Puducherry','35'=>'Andaman and Nicobar Islands','36'=>'Telangana','37'=>'Andhra Pradesh','38'=>'Ladakh'];}
 public static function text(array $d,string $k,int $max,bool $required=false):string {$v=$d[$k]??'';if(!is_string($v) || mb_strlen(trim($v))>$max || ($required && trim($v)===''))throw new DomainException('Enter a valid '.str_replace('_',' ',$k).'.');return trim($v);}
 public static function state(string $v):string {if(!isset(self::states()[$v]))throw new DomainException('Choose a valid state.');return $v;}
 public static function gstin(string $v,string $state,bool $required=false):?string {$v=strtoupper(trim($v));if($v===''){if($required)throw new DomainException('GSTIN is required for registered businesses.');return null;}if(!preg_match('/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/D',$v) || substr($v,0,2)!==$state)throw new DomainException('GSTIN format or state does not match.');return $v;}
 public function get(bool $required=true,bool $lock=false):?array {$q=db()->prepare('SELECT st.*,t.rate AS default_rate FROM shop_tax_settings st LEFT JOIN tax_rates t ON t.shop_id=st.shop_id AND t.id=st.default_tax_rate_id WHERE st.shop_id=?'.($lock?' FOR UPDATE':''));$q->execute([$this->shop]);$s=$q->fetch();if(!$s && $required)throw new DomainException('The owner must configure shop tax and invoice settings before billing.');return $s?:null;}
 public function save(array $d,array $actor):void {
  if(($actor['role']??'')!=='shop_owner' || (int)$actor['shop_id']!==$this->shop)throw new DomainException('Shop owner access required.');
  $legal=self::text($d,'legal_name',150,true);$address=self::text($d,'address',500,true);$state=self::state(self::text($d,'state_code',2,true));$type=self::text($d,'registration_type',20,true);if(!in_array($type,['regular','composition','unregistered'],true))throw new DomainException('Choose a registration type.');
  $gst=self::gstin(self::text($d,'gstin',15),$state,$type!=='unregistered');if($type==='unregistered' && $gst)throw new DomainException('Unregistered businesses cannot use a GSTIN.');
  $mode=self::text($d,'price_mode',20,true);if(!in_array($mode,['inclusive','exclusive'],true))throw new DomainException('Choose a price mode.');$prefix=self::text($d,'invoice_prefix',4,true);if(!preg_match('/^[A-Za-z0-9]{1,4}$/D',$prefix))throw new DomainException('Invoice prefix must be 1–4 letters or digits.');
  $tax=ProductService::optionalId($d['default_tax_rate_id']??'');if($tax){$q=db()->prepare("SELECT id FROM tax_rates WHERE shop_id=? AND id=? AND status='active'");$q->execute([$this->shop,$tax]);if(!$q->fetchColumn())throw new DomainException('Choose an active configured tax rate.');}
  db()->prepare('INSERT INTO shop_tax_settings(shop_id,legal_name,address,state_code,registration_type,gstin,price_mode,default_tax_rate_id,require_hsn,invoice_prefix,footer) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE legal_name=VALUES(legal_name),address=VALUES(address),state_code=VALUES(state_code),registration_type=VALUES(registration_type),gstin=VALUES(gstin),price_mode=VALUES(price_mode),default_tax_rate_id=VALUES(default_tax_rate_id),require_hsn=VALUES(require_hsn),invoice_prefix=VALUES(invoice_prefix),footer=VALUES(footer)')->execute([$this->shop,$legal,$address,$state,$type,$gst,$mode,$tax,isset($d['require_hsn'])?1:0,$prefix,self::text($d,'footer',300)]);
 }
}
